\label{ASS:prop1}
For any $\delta>0$ and $M\geq 1,$ the lower limit of $N^{-1}\mathbb{E}\log Z_N$ is bounded from below by
\begin{align}
\begin{split}\label{ASS:prop1:eq1}
&\frac{1}{M}\liminf_{N\rightarrow\infty}\left(\mathbb{E}\log \int_{S_M}\left<\exp \vec{\varepsilon}\cdot \vec{z} ({\vec{\sigma}})\right>_{M,N}d\lambda_M(\vec{\varepsilon})-
\mathbb{E}\log \left<\exp \sqrt{M}y({\vec{\sigma}})\right>_{M,N}\right)\\
&\qquad\qquad -\delta\xi'(1)+\frac{1}{M}\log \nu_M(A_\delta),
\end{split}
\end{align}
where $\nu_M$ is the probability measure of the $M$-dimensional Gaussian density and 
$$
A_\delta=\{\vec{\varepsilon}\in\mathbb{R}^M:M\leq\|\vec{\varepsilon}\|^2\leq M(1+\delta)\}.
$$

Using the rotational invariance of $\nu_M,$ there  exists a probability measure $\gamma_M$ on $\mathbb{R}^+$ such that
$\nu_M$ is the image of $\gamma_M\times \lambda_M$ under the map $(s,\vec{\varepsilon})
\mapsto s\vec{\varepsilon}.$ For $1\leq s\leq (1+\delta)^{1/2}$, using symmetry,
\begin{align*}
\int \exp s\vec{\varepsilon}\cdot\vec{z} d\lambda_M(\vec{\varepsilon})&=\int \cosh(s\vec{\varepsilon}\cdot\vec{z})d\lambda_M(\vec{\varepsilon})\\
&\geq \int \cosh(\vec{\varepsilon}\cdot\vec{z})d\lambda_M(\vec{\varepsilon})=\int \exp \vec{\varepsilon}\cdot\vec{z} d\lambda_M(\vec{\varepsilon}).
\end{align*} 
Therefore, $(\ref{ASS:lem5:eq1})$ holds by
\begin{align*}
\int_{A_\delta}\exp \vec{\varepsilon}\cdot\vec{z} d\nu_M(\vec{\varepsilon})&=\int_{1}^{(1+\delta)^{1/2}}\int_{S_M}\exp s\vec{\varepsilon}\cdot \vec{z} d\lambda_M(\vec{\varepsilon})d\gamma_M(s)\\
&\geq\int_{1}^{(1+\delta)^{1/2}}\int_{S_M}\exp\vec{\varepsilon}\cdot \vec{z} d\lambda_M(\vec{\varepsilon})d\gamma_M(s)\\
&= \gamma_M(\{1\leq s\leq (1+\delta)^{1/2}\})\int_{S_M}\exp\vec{\varepsilon}\cdot \vec{z} d\lambda_M(\vec{\varepsilon}).
\end{align*}

Suppose $(y'({\vec{\sigma}}):{\vec{\sigma}}\in S_N)$ is a family of centered Gaussian random variables independent of all the other randomness such that in distribution
\begin{align*}
H_N({\vec{\sigma}})=H_{M,N}({\vec{\sigma}})+\sqrt{M}y'({\vec{\sigma}}).
\end{align*}
It is easy to check that 
$\mathbb{E}y'({\vec{\sigma}}^1)y'({\vec{\sigma}}^2)=\sum_{p\geq 1}\beta_p^2D_pN^pR({\vec{\sigma}}^1,{\vec{\sigma}}^2)^{p}$, where $$
D_{p}=\frac{1}{M}\left(\frac{1}{N^{p-1}}-\frac{1}{(M+N)^{p-1}}\right)
$$ 
satisfies $N^pD_{p}\rightarrow p-1.$ Recall $y({\vec{\sigma}})$ from $(\ref{ASS:eq0.2}).$ Let us consider the interpolating free energy
\begin{align*}
\psi(t)&=\mathbb{E}\log \left<\exp \sqrt{M}\left(\sqrt{t}y'({\vec{\sigma}})+\sqrt{1-t}{y}({\vec{\sigma}})\right)\right>_{M,N}.
\end{align*}
Then $|\psi(1)-\psi(0)|$ gives the quantity in the limit on the left-hand side of $(\ref{ASS:lem4:eq1})$. Thus it suffices to prove that $\psi'(t)\rightarrow 0$ uniformly in $t\in (0,1)$ as $N\rightarrow\infty,$ which can be easily verified by using Gaussian integration by parts, as $N\rightarrow\infty,$
\begin{align*}
\sup_{0<t<1}|\psi'(t)|&\leq M\sup_{{\vec{\sigma}}^1,{\vec{\sigma}}^2\in S_N}|\mathbb{E}y'({\vec{\sigma}}^1)y'({\vec{\sigma}}^2)-\mathbb{E}y({\vec{\sigma}}^1)y({\vec{\sigma}}^2)|\\
&=M\sup_{{\vec{\sigma}}^1,{\vec{\sigma}}^2\in S_N}\left|\sum_{p\geq 1}\beta_p^2(D_{p}N^p-(p-1))R({\vec{\sigma}}^1,{\vec{\sigma}}^2)^p\right|\rightarrow 0.
\end{align*}

\label{ASS:lem1}
Suppose that $f$ is a nonnegative function defined on $S_{M+N}.$ 
Then we have 
\begin{align}\label{ASS:lem1:eq1}
\int_{S_{M+N}}f({\vec{\rho}})d\lambda_{M+N}({\vec{\rho}})
&=\int_{A_{M,N}}
F_{M,N}(\vec{\varepsilon})d\boldsymbol{\varepsilon}\int_{S_N}f\left({\vec{\sigma}} a_{M+1},\varepsilon_{1}a_{1},\ldots,\varepsilon_Ma_M\right)d\lambda_{N}({\vec{\sigma}}).
\end{align}

This is an elementary calculus formula that follows by an induction argument starting from  
\begin{align*}
\int_{S_K}f({\vec{\rho}})d\lambda_K({\vec{\rho}})&=\frac{|S_{K-1}^1|}{|S_K^1|\sqrt{K}}\int_{-\sqrt{K}}^{\sqrt{K}}\left(1-\frac{\varepsilon^2}{K}\right)^{\frac{K-3}{2}}d\varepsilon \int_{S_{K-1}}f\left({\vec{\sigma}} \sqrt{\frac{K-\varepsilon^2}{K-1}},\varepsilon\right)d\lambda_{K-1}({\vec{\sigma}})
\end{align*}
for every $K\geq 2.$

Suppose that $(H_{M,N}'({\vec{\sigma}}):{\vec{\sigma}}\in S_N)$ is an independent copy of $(H_{M,N}({\vec{\sigma}}):{\vec{\sigma}}\in S_N)$ and is independent of all the other randomness.
We consider the following interpolating Hamiltonian
\begin{align*}
\varphi(t)=&\mathbb{E}\log\int_{A_\delta}F_{M,N}(\vec{\varepsilon})d\vec{\varepsilon}\int_{S_N}\exp(H_{1,t}({\vec{\rho}})+H_{2,t}({\vec{\rho}})+H_{3,t}({\vec{\rho}}))d
\lambda_N({\vec{\sigma}}),
\end{align*}
where for ${\vec{\rho}}=({\vec{\sigma}},\vec{\varepsilon})$ with ${\vec{\sigma}}\in S_N$ and $\vec{\varepsilon}\in A_\delta,$
\begin{align*}
H_{1,t}({\vec{\rho}})&=\sqrt{t}H_{M,N}({\vec{\sigma}} a_{M+1})+\sqrt{1-t}H_{M,N}'({\vec{\sigma}})\\
H_{2,t}({\vec{\rho}})&=\sum_{i\leq M}\varepsilon_i\left(\sqrt{t}a_i Z_i({\vec{\sigma}} a_{M+1})+\sqrt{1-t}z_i({\vec{\sigma}})\right)\\
H_{3,t}({\vec{\rho}})&=\sqrt{t}\gamma({\vec{\sigma}} a_{M+1},\varepsilon_1a_1,\ldots,\varepsilon_Ma_M).
\end{align*}
From $(\ref{ASS:lem1:eq1})$, obviously $\varphi(1)\leq\mathbb{E}\log Z_{M+N}$ when $N$ is large enough. On the other hand, using Gaussian integration by parts and replicas ${\vec{\rho}}^1=({\vec{\sigma}}^1,\vec{\varepsilon}^1)$ and ${\vec{\rho}}^2=({\vec{\sigma}}^2,\vec{\varepsilon}^2),$ it follows that
\begin{align*}
\varphi'(t)=\frac{1}{2}\sum_{j\leq 3}\left(\mathbb{E}\left<U_{j}({\vec{\rho}},{\vec{\rho}})\right>_t-\mathbb{E}\left<U_j({\vec{\rho}}^1,{\vec{\rho}}^2)\right>_t\right),
\end{align*}
where $\left<\cdot\right>_t$ is the Gibbs average corresponding to random weights $F_{M,N}\exp(H_{1,t}+H_{2,t}+H_{3,t})$ with reference measure
$\lambda_N\times d\vec{\varepsilon}$ on $S_N\times A_\delta$ and
\begin{align*}
U_1({\vec{\rho}}^1,{\vec{\rho}}^2)&=\mathbb{E}H_{M,N}({\vec{\sigma}}^1a_{M+1}(\vec{\varepsilon}^1))H_{M,N}({\vec{\sigma}}^2a_{M+1}(\vec{\varepsilon}^2))-
\mathbb{E}H_{M,N}'({\vec{\sigma}}^1)H_{M,N}'({\vec{\sigma}}^2)\\
U_2({\vec{\rho}}^1,{\vec{\rho}}^2)&=\sum_{i\leq M}\varepsilon_i^1\varepsilon_i^2\left(a_i(\vec{\varepsilon}^1)a_{i}(\vec{\varepsilon}^2)\mathbb{E}Z_i({\vec{\sigma}}^1a_{M+1}(\vec{\varepsilon}^1))Z_i({\vec{\sigma}}^2a_{M+1}(\vec{\varepsilon}^2))
-\mathbb{E}z_i({\vec{\sigma}}^1)z_i({\vec{\sigma}}^2)\right)\\
U_3({\vec{\rho}}^1,{\vec{\rho}}^2)&=\mathbb{E}\gamma({\vec{\sigma}}^1a_{M+1}(\vec{\varepsilon}^1),\eps_1^1a_1(\vec{\varepsilon}^1),\ldots,\eps_M^1a_M(\vec{\varepsilon}^1))\\
&\qquad\cdot\gamma({\vec{\sigma}}^2a_{M+1}(\vec{\varepsilon}^2),\eps_1^2a_1(\vec{\varepsilon}^2),\ldots,\eps_M^2a_M(\vec{\varepsilon}^2)).
\end{align*}
From $(\ref{ASS:eq0.1})$, $(\ref{ASS:eq2.2}),$ and $(\ref{ASS:eq2.3})$, it is easy to see that for $j=2,3,$
$$\lim_{N\rightarrow\infty}\sup_{{\vec{\rho}}^1,{\vec{\rho}}^2\in S_N\times A_\delta}|U_j({\vec{\rho}}^1,{\vec{\rho}}^2)|\rightarrow 0$$
and from $(\ref{ASS:eq2.1})$ and using mean value theorem,
\begin{align*}
&\lim_{N\rightarrow\infty}\sup_{{\vec{\rho}}^1,{\vec{\rho}}^2\in S_N\times A_\delta}|U_1({\vec{\rho}}^1,{\vec{\rho}}^2)|\\
&\leq \lim_{N\rightarrow\infty}\xi'(1)(M+N)\sup_{\vec{\varepsilon}^1,\vec{\varepsilon}^2\in A_\delta}\left|\frac{N}{M+N}a_{M+1}(\vec{\varepsilon}^1)a_{M+1}(\vec{\varepsilon}^2)-1\right|\\
&=\xi'(1)\sup_{\vec{\varepsilon}^1,\vec{\varepsilon}^2\in A_\delta}\left|M-\frac{\|\vec{\varepsilon}^1\|^2+\|\vec{\varepsilon}^2\|^2}{2}\right|\leq M\delta\xi'(1).
\end{align*}
Thus we conclude that $\limsup_{N\rightarrow\infty}\sup_{0<t<1}|\varphi'(t)|\leq M\delta\xi'(1)$ and so $(\ref{ASS:lem2:eq1})$ follows by
\begin{align*}
\liminf_{N\rightarrow\infty}\mathbb{E}\log \frac{Z_{M+N}}{\int_{A_\delta}F_{M,N}J_{M,N}d\vec{\varepsilon}}&\geq \liminf_{N\rightarrow\infty}(\varphi(1)-\varphi(0))\\
&\geq -\limsup_{N\rightarrow\infty}\sup_{0<t<1}|\varphi'(t)|\geq -M\delta\xi'(1).
\end{align*}

Using the inequality $\log(1-x)\geq -2x$ for $0<x<1/2,$ when $N$ is sufficiently large, we have for every $\vec{\varepsilon}\in A_\delta,$
\begin{align*}
&\log \frac{F_{M,N}(\vec{\varepsilon})}{F_M(\vec{\varepsilon})}\\
&=\log b_{M,N}-\frac{M}{2}\log\frac{1}{2\pi}+\sum_{j=1}^M\frac{M+N-j-2}{2}\log\left(1-\frac{\varepsilon_j^2}{M+N+1-j}\right)+\frac{\|\vec{\varepsilon}\|^2}{2}\\
&\geq \log b_{M,N}-\frac{M}{2}\log\frac{1}{2\pi}+\frac{3\|\vec{\varepsilon}\|^2}{M+N}.
\end{align*}
Note that $\lim_{N\rightarrow\infty}b_{M,N}=1/(2\pi)^{M/2}$ as can be seen from $(\ref{ASS:lem1:eq1})$ with $f=1.$ By Jensen's inequality, we obtain
\begin{align*}
&\liminf_{N\rightarrow\infty}\mathbb{E}\log\frac{\int_{A_\delta}F_MJ_{M,N}\exp \left(\log F_{M,N}/F_{M}\right)d\vec{\varepsilon}}{\int_{A_\delta}F_MJ_{M,N}d\vec{\varepsilon}}\\
&\geq \liminf_{N\rightarrow\infty}\mathbb{E}\frac{\int_{A_\delta}F_MJ_{M,N}\log F_{M,N}/F_{M}d\vec{\varepsilon}}{\int_{A_\delta}F_MJ_{M,N}d\vec{\varepsilon}}\\
&\geq \liminf_{N\rightarrow\infty}\left(\log b_{M,N}-\frac{M}{2}\log \frac{1}{2\pi}+\frac{3M}{M+N}\right)=0
\end{align*}
and this gives $(\ref{ASS:lem3:eq1}).$

\label{ASS:cor} Recall $A_\delta$ and $\nu_M$ from Theorem $\ref{ASS:prop1}.$
For every $\delta>0$ and $M\geq 1,$ we have
\begin{align}
\begin{split}\label{ASS:cor:eq1}
&\liminf_{N\rightarrow\infty}\frac{1}{N}\mathbb{E}\log Z_N\\
&\geq\frac{1}{M}\liminf_{N\rightarrow\infty}\sup_{u}\left(\mathbb{E}\log \int_{S_M}\left<\exp \vec{\varepsilon}\cdot \vec{z} ({\vec{\sigma}})\right>_{M,N}^-d\lambda_M(\vec{\varepsilon})-
\mathbb{E}\log \left<\exp \sqrt{M}y({\vec{\sigma}})\right>_{M,N}^-\right)\\
&\qquad\qquad -\delta\xi'(1)+\frac{1}{M}\log \nu_M(A_\delta),
\end{split}
\end{align}
where the supremum is taken over all $u=(u_{p})_{p\geq 1}$ with $1\leq u_p\leq 2.$

\label{prop:GG}
For $M\geq 1$, we have 
\begin{align}\label{prop:GG:eq1}
\lim_{N\rightarrow\infty}\mathbb{E}_u\Phi_{M,N}(p,n,f)=0
\end{align}
for all $(p,n,f)\in\mathcal{C},$ where we view $u=(u_p)_{p\geq 1}$ as a sequence of i.i.d. uniform random variables on $\left[1,2\right]$ and $\mathbb{E}_u$ is the expectation with respect to the randomness of $u.$

\label{AGM:Prop1}
If $(R_{\ell,\ell'})_{\ell,\ell'\geq 1}$ is a Gram-de Finetti array such that $R_{\ell,\ell}=1$, then there exists a random measure $G$ on the unit ball of a separable Hilbert space such that
\begin{align*}

\left(R_{\ell,\ell'}\right)_{\ell,\ell'\geq 1}\stackrel{d}{=}\left(\vec{\tau}^{\ell}\cdot\vec{\tau}^{\ell'}+\delta_{\ell,\ell'}(1-\|\vec{\tau}^{\ell}\|^2)\right)_{\ell,\ell'\geq 1},
\end{align*}
where $(\vec{\tau}^\ell)$ is an i.i.d. sample from $G.$

 \label{AGM:prop21}
For any two triplets $(k,\mathbf{m},\mathbf{q})$ and $(k',\mathbf{m}',\mathbf{q}')$ associated with the distribution functions $\vec{x}$ and $\vec{x}'$ respectively, we have
\begin{align}
\label{AGM:prop2}
\left|\mathcal{P}_M(\vec{x})-\mathcal{P}_M(\vec{x}')\right|\leq \frac{\xi'(1)}{2}\int_0^1\left|\vec{x}(q)-\vec{x}'(q)\right|dq.
\end{align}

Thus by the Dovbysh-Sudakov representation, $R_{k}^M$ can be generated by a sample from a random measure $G_M^k$ on the unit ball of some Hilbert space.
Since $\sup_{0\leq q\leq 1}|H_k(q)-q|\leq 1/k,$ $(R_k^M)_{k\geq 1}$ converges weakly to $R^M.$ From Lemma $\ref{AGM:lem2},$ we then obtain
\begin{align}\label{AGMU:add1}
\lim_{k\rightarrow\infty}\Psi_M(\mathcal{L}_k^M)=\Psi_M(\mathcal{L}^M),
\end{align}  
where $\mathcal{L}_k^M$ is the distribution for $R_k^M$. On the other hand, from the Baffioni-Rosati theorem \cite{BR00}, an ultrametric measure, such as $G_M^k$, that satisfies the G.G. identities and under which the overlaps $R_k^M$ take finitely many values $(p/k)_{0\leq p\leq k}$ can be identified as the Poisson-Dirichlet cascade with parameters 
\begin{align*}
\mathbf{m}^{M,k}&=(m_p^{M,k})_{0\leq p\leq k}\,\,\mbox{with $m_p^{M,k}=\mathbb{E}\left<I((R_k^M)_{1,2}\leq p/k)\right>_M,$}\\
\mathbf{q}^{M,k}&=(q_p^{M,k})_{0\leq p\leq k+1}\,\,\mbox{with $q_p^{M,k}=p/(k+1)$}.
\end{align*}
For details of this result, one may consult the proof of Theorem 15.3.6 in \cite{Tal11}. Let $\vec{x}_k^M$ be the distribution function corresponding to this triplet $(k,\mathbf{m}^{M,k},\mathbf{q}^{M,k}).$ Using the same argument as Theorem 14.2.1 in \cite{Tal11}, we obtain
\begin{align}\label{AGM:eq6}
\Psi_M(\mathcal{L}_k^M)=\mathcal{P}_M(\vec{x}_k^M).
\end{align}

\noindent{\bf Proof of Theorem \ref{ASS:prop1}.}
From $(\ref{ASS:main:eq0})$, $(\ref{ASS:main:eq1})$, and $(\ref{sec2:eq1}),$ using Lemmas  $\ref{ASS:lem4},$ $\ref{ASS:lem2}$, and $\ref{ASS:lem3},$ the lower limit of 
$N^{-1}{\mathbb{E}\log Z_{N}}$ is bounded from below by
\begin{align*}
\frac{1}{M}\liminf_{N\rightarrow\infty}\left(\mathbb{E}\log\int_{A_\delta}\left<\exp \vec{\varepsilon}\cdot\vec{z}({\vec{\sigma}})\right>_{M,N}d\nu_M(\vec{\varepsilon})-\mathbb{E}\log \left<\exp\sqrt{M}y({\vec{\sigma}})\right>_{M,N}\right)-\delta\xi'(1)
\end{align*}
and then  $(\ref{ASS:lem5.1:eq1})$ yields $(\ref{ASS:prop1:eq1}).$\qed

